from pathlib import Path
import json


def text(en, de):
    return {'en': en, 'de': de}


def task(identifier, title, emoji, prompt, groups):
    categories=[]
    items=[]
    slots=[]
    for category, en, de, symbol, description, rows in groups:
        categories.append({'id':category,'label':text(en,de),'icon':{'emoji':symbol,'motion':'float'},'description':text(*description)})
        slot=[]
        for index, (item, en, de, reason_en, reason_de) in enumerate(rows):
            items.append({'id':item,'label':text(en,de),'icon':{'emoji':symbol,'motion':['bounce','pulse','spin','sway','flip'][index]},'category':category,'explanation':text(reason_en,reason_de)})
            slot.append(item)
        slots.append(slot)
    return {'kind':'classification','id':identifier,'title':text(*title),'icon':{'emoji':emoji,'motion':'pulse'},'prompt':text(*prompt),'categories':categories,'items':items,'draw':len(slots),'pool':{'seconds':300,'slots':slots}}


data=task('data-information',('Data and Information','Daten und Information'),'🔎',(
    'Classify the representation at the stated level of interpretation. Data means recorded symbols or values without the building meaning needed here. Information means those data interpreted through an explicit building concept, unit, relationship or requirement. A coordinate table may become information once its context is known; the raw tables here deliberately lack that context. BIM objects connect geometry with meaning. Allow five minutes.',
    'Ordne die Darstellung nach ihrer angegebenen Interpretation ein. Daten sind aufgezeichnete Zeichen oder Werte ohne die hier benötigte Gebäudebedeutung. Information entsteht durch ihre Deutung als Bauteil, Einheit, Beziehung oder Anforderung. Eine Koordinatentabelle kann mit Kontext Information werden; den Rohdaten hier fehlt dieser Kontext bewusst. BIM-Objekte verbinden Geometrie mit Bedeutung. Plane fünf Minuten ein.'),[
    ('data','Data','Daten','🔢',('Recorded values without sufficient building interpretation in this exercise.','Aufgezeichnete Werte ohne ausreichende Gebäudedeutung in dieser Aufgabe.'),[
        ('coordinate-table','Unlabelled x/y/z coordinate table','Unbeschriftete x/y/z-Tabelle','The rows contain positions, but no units, coordinate system or object identity. They do not yet tell us that the points belong to a door.','Die Zeilen enthalten Positionen, aber weder Einheit noch Koordinatensystem oder Objektidentität. Dass die Punkte zu einer Tür gehören, geht daraus noch nicht hervor.'),
        ('unlabelled-values','Unlabelled values 900 and 2100','Unbeschriftete Werte 900 und 2100','The numbers could represent dimensions, identifiers or prices. Without quantities and units, their intended building meaning is undetermined.','Die Zahlen könnten Abmessungen, Kennungen oder Preise sein. Ohne Größenbezeichnung und Einheit bleibt ihre Gebäudebedeutung unbestimmt.'),
        ('anonymous-triangles','Triangles without element identity','Dreiecke ohne Bauteilzuordnung','A triangle mesh records shape. Without classification or relationships it does not identify a wall, a door or its purpose.','Ein Dreiecksnetz speichert Form. Ohne Klassifikation und Beziehungen kennzeichnet es weder Wand noch Tür oder deren Zweck.'),
        ('unmapped-code','Unmapped material code M17','Materialcode M17 ohne Zuordnung','M17 is a stored symbol. A material dictionary or linked definition is needed before it can communicate a material specification.','M17 ist ein gespeichertes Zeichen. Erst ein Materialverzeichnis oder eine verknüpfte Definition vermittelt die Materialfestlegung.'),
        ('raw-temperature-log','Sensor values without units','Sensorwerte ohne Einheiten','A sequence such as 21, 22, 23 lacks the measured quantity, location and unit. The log alone cannot establish room temperature.','Einer Folge wie 21, 22, 23 fehlen Messgröße, Ort und Einheit. Das Protokoll allein beschreibt deshalb keine Raumtemperatur.')]),
    ('information','Information','Information','🚪',('Values with explicit building meaning and relevant context.','Werte mit ausdrücklicher Gebäudebedeutung und relevantem Kontext.'),[
        ('door-object','Door D12 in wall W3','Tür D12 in Wand W3','The geometry is identified as a door and related to a host wall. Object identity and relationship add building meaning to coordinates.','Die Geometrie ist als Tür identifiziert und einer Wand zugeordnet. Objektidentität und Beziehung geben den Koordinaten Gebäudebedeutung.'),
        ('fire-rating-meaning','Door fire resistance: 30 minutes','Feuerwiderstand der Tür: 30 Minuten','The value has a quantity, duration unit and a link to a door. It communicates a specified performance rather than an isolated number.','Der Wert besitzt Größe, Zeiteinheit und Türbezug. Er vermittelt eine festgelegte Eigenschaft statt einer isolierten Zahl.'),
        ('room-area-meaning','Room R4 floor area: 24 square metres','Grundfläche von Raum R4: 24 m²','The number 24 becomes usable information through the room identity, measured property and square-metre unit.','Die Zahl 24 wird durch Raumidentität, gemessene Eigenschaft und Quadratmetereinheit zu nutzbarer Information.'),
        ('door-width-meaning','Door D12 clear width: 0.90 metres','Lichte Breite von Tür D12: 0,90 m','Object identity, clear width and metres specify what 0.90 means. The statement can support a width check against an explicit requirement.','Objektidentität, lichte Breite und Meter legen die Bedeutung von 0,90 fest. Damit lässt sich eine ausdrücklich vorgegebene Breitenanforderung prüfen.'),
        ('wall-layer-meaning','Wall W3 exterior insulation layer','Außendämmschicht von Wand W3','The layer is classified as insulation, placed outside and related to wall W3. Those semantics communicate construction intent beyond shape.','Die Schicht ist als Dämmung klassifiziert, außen angeordnet und Wand W3 zugeordnet. Diese Semantik vermittelt den Konstruktionszweck über die Form hinaus.')])])

oop=task('object-oriented-model',('Object Orientation in BIM','Objektorientierung im BIM'),'🧩',(
    'Identify the object-oriented concept highlighted in each schematic model statement. A class defines a type; an instance is one identified object; an attribute stores a property; a method performs an operation. Inheritance expresses is-a specialization; composition expresses an owned part-of relationship. Treat these as conceptual software examples: a BIM authoring application need not implement the shown methods or classes literally. Allow five minutes.',
    'Bestimme das hervorgehobene objektorientierte Konzept jeder schematischen Modellaussage. Eine Klasse definiert einen Typ, eine Instanz ein einzelnes identifiziertes Objekt, ein Attribut speichert eine Eigenschaft und eine Methode führt eine Operation aus. Vererbung beschreibt eine Ist-ein-Spezialisierung, Komposition eine besitzende Teil-von-Beziehung. Dies sind konzeptionelle Softwarebeispiele; ein BIM-Programm muss die gezeigten Methoden oder Klassen nicht wörtlich umsetzen. Plane fünf Minuten ein.'),[
    ('class','Class','Klasse','📋',('A reusable definition of a type with its properties and operations.','Wiederverwendbare Typdefinition mit Eigenschaften und Operationen.'),[
        ('door-class','Blueprint defining the Door type','Bauplan des Typs Tür','Door defines the shared structure from which individual doors can be instantiated. The statement describes the type, not a particular installed door.','Tür definiert die gemeinsame Struktur, aus der einzelne Türen erzeugt werden können. Gemeint ist der Typ und keine bestimmte eingebaute Tür.'),
        ('wall-class','Blueprint defining the Wall type','Bauplan des Typs Wand','The Wall definition specifies the properties and operations available to walls. It is a class even before a wall object exists.','Die Definition Wand legt Eigenschaften und Operationen für Wände fest. Sie ist bereits eine Klasse, bevor ein Wandobjekt existiert.'),
        ('room-class','Blueprint defining the Room type','Bauplan des Typs Raum','The Room type describes what all room objects can store or do. It does not identify one room such as R4.','Der Typ Raum beschreibt, was alle Raumobjekte speichern oder ausführen können. Er kennzeichnet keinen einzelnen Raum wie R4.'),
        ('window-class','Blueprint defining the Window type','Bauplan des Typs Fenster','The reusable Window definition is the class. Individual windows may share it while carrying different widths and identities.','Die wiederverwendbare Definition Fenster ist die Klasse. Einzelne Fenster können sie teilen und dennoch unterschiedliche Breiten und Identitäten besitzen.'),
        ('column-class','Blueprint defining the Column type','Bauplan des Typs Stütze','Column defines the common object type. The definition is separate from the many particular columns created from it.','Stütze definiert den gemeinsamen Objekttyp. Die Definition ist von den vielen daraus erzeugten einzelnen Stützen zu unterscheiden.')]),
    ('instance','Instance','Instanz','🏷️',('One identified object created according to a class.','Ein einzelnes identifiziertes Objekt gemäß einer Klasse.'),[
        ('door-instance','Door object D12 on level 2','Türobjekt D12 im zweiten Geschoss','D12 identifies one door object with its own position and values. Many other door instances can use the same class.','D12 kennzeichnet ein Türobjekt mit eigener Position und eigenen Werten. Viele weitere Türinstanzen können dieselbe Klasse nutzen.'),
        ('wall-instance','Wall object W3 along grid A','Wandobjekt W3 an Achse A','W3 names one particular wall. Its identity distinguishes the instance from the generic Wall definition.','W3 benennt eine bestimmte Wand. Ihre Identität unterscheidet die Instanz von der allgemeinen Definition Wand.'),
        ('room-instance','Room object R4 beside the stair','Raumobjekt R4 neben der Treppe','R4 refers to a particular room object. Its location is instance data rather than the definition of every room.','R4 bezeichnet ein bestimmtes Raumobjekt. Seine Lage gehört zur Instanz und nicht zur Definition aller Räume.'),
        ('window-instance','Window object F8 on the east facade','Fensterobjekt F8 an der Ostfassade','F8 is one identified window. The Window class can also define other windows with different locations.','F8 ist ein identifiziertes Fenster. Die Klasse Fenster kann daneben weitere Fenster an anderen Orten beschreiben.'),
        ('column-instance','Column object C5 at grid B2','Stützenobjekt C5 an Achse B2','C5 is the concrete model object at B2. The generic Column type does not prescribe this one identity or location.','C5 ist das konkrete Modellobjekt an B2. Der allgemeine Typ Stütze schreibt diese einzelne Identität oder Lage nicht vor.')]),
    ('attribute','Attribute','Attribut','📏',('A stored value describing an object property.','Ein gespeicherter Wert für eine Objekteigenschaft.'),[
        ('door-width','Width value of door D12','Breitenwert der Tür D12','The width is a property value, for example 0.90 m. Reading that value does not itself execute a door operation.','Die Breite ist ein Eigenschaftswert, beispielsweise 0,90 m. Das Lesen dieses Werts führt noch keine Türoperation aus.'),
        ('wall-thickness','Thickness value of wall W3','Dickenwert der Wand W3','Thickness stores a length associated with W3. It is an attribute rather than a class or a procedure.','Die Dicke speichert eine W3 zugeordnete Länge. Sie ist ein Attribut und weder eine Klasse noch eine Prozedur.'),
        ('room-name','Name value of room R4','Namenswert des Raums R4','The room name is a stored text property. Attributes can contain text as well as numbers.','Der Raumname ist eine gespeicherte Texteigenschaft. Attribute können neben Zahlen auch Texte enthalten.'),
        ('window-u-value','U-value property of window F8','U-Wert-Eigenschaft des Fensters F8','The stored thermal-transmittance value describes F8. A property can have a physical unit without becoming an operation.','Der gespeicherte Wärmedurchgangskoeffizient beschreibt F8. Auch eine Eigenschaft mit physikalischer Einheit bleibt ein Attribut und keine Operation.'),
        ('column-material','Material value of column C5','Materialwert der Stütze C5','The material reference describes what C5 is made of. The statement highlights a stored property, not a material-changing method.','Der Materialverweis beschreibt den Werkstoff von C5. Hervorgehoben wird die gespeicherte Eigenschaft und keine Methode zum Materialwechsel.')]),
    ('method','Method','Methode','⚙️',('An operation defined for an object or its type.','Eine für ein Objekt oder seinen Typ definierte Operation.'),[
        ('door-open','Open operation of door D12','Öffnungsoperation der Tür D12','Open changes the schematic door state when invoked. It is an operation; the current opening angle would instead be an attribute.','Öffnen ändert beim Aufruf den schematischen Türzustand. Es ist eine Operation; der aktuelle Öffnungswinkel wäre dagegen ein Attribut.'),
        ('wall-volume-method','Volume calculation of wall W3','Volumenberechnung der Wand W3','The method calculates a result from the wall geometry. The stored result may be an attribute, but calculation is the operation.','Die Methode berechnet ein Ergebnis aus der Wandgeometrie. Das gespeicherte Ergebnis kann ein Attribut sein; die Berechnung ist die Operation.'),
        ('room-rename-method','Rename operation of room R4','Umbenennungsoperation von Raum R4','Rename performs a change to the room name. The operation differs from the name value that it updates.','Umbenennen verändert den Raumnamen. Die Operation unterscheidet sich von dem Namenswert, den sie aktualisiert.'),
        ('window-rotate-method','Rotation operation of window F8','Drehoperation des Fensters F8','Rotate is invoked to transform the window object. Orientation is a property; changing it is an operation.','Drehen wird aufgerufen, um das Fensterobjekt zu transformieren. Die Orientierung ist eine Eigenschaft; ihre Änderung ist eine Operation.'),
        ('column-move-method','Move operation of column C5','Verschiebeoperation der Stütze C5','Move performs a transformation on C5. The resulting location may be stored as an attribute after the method completes.','Verschieben führt eine Transformation an C5 aus. Die resultierende Lage kann nach Abschluss der Methode als Attribut gespeichert werden.')]),
    ('inheritance','Inheritance','Vererbung','🌳',('An is-a specialization that derives from a more general class.','Eine Ist-ein-Spezialisierung einer allgemeineren Klasse.'),[
        ('firedoor-inheritance','FireDoor as a subtype of Door','Brandschutztür als Untertyp von Tür','Every FireDoor in this model is a Door with additional fire-related properties. This is an is-a relation between types.','Jede Brandschutztür ist in diesem Modell eine Tür mit zusätzlichen Brandschutzeigenschaften. Das ist eine Ist-ein-Beziehung zwischen Typen.'),
        ('curtainwall-inheritance','CurtainWall as a subtype of Wall','Vorhangfassade als Untertyp von Wand','In this schematic hierarchy a CurtainWall inherits the common Wall definition and specializes it. The stated is-a relationship is inheritance.','In dieser schematischen Hierarchie übernimmt Vorhangfassade die allgemeine Definition Wand und spezialisiert sie. Die angegebene Ist-ein-Beziehung ist Vererbung.'),
        ('office-inheritance','Office as a subtype of Room','Büro als Untertyp von Raum','Office is a specialized Room type in this exercise. An office is a room; it is not a component owned by the Room class.','Büro ist in dieser Aufgabe ein spezialisierter Raumtyp. Ein Büro ist ein Raum und kein Bauteil im Besitz der Klasse Raum.'),
        ('roofwindow-inheritance','RoofWindow as a subtype of Window','Dachfenster als Untertyp von Fenster','RoofWindow derives shared properties from Window and adds specialization. The relation connects a specific type to its more general type.','Dachfenster übernimmt gemeinsame Eigenschaften von Fenster und ergänzt eine Spezialisierung. Die Beziehung verbindet einen spezielleren mit einem allgemeineren Typ.'),
        ('steelcolumn-inheritance','SteelColumn as a subtype of Column','Stahlstütze als Untertyp von Stütze','SteelColumn specializes Column in the stated hierarchy. An individual C5 made from steel would instead be an instance with a material value.','Stahlstütze spezialisiert Stütze in der angegebenen Hierarchie. Eine einzelne C5 aus Stahl wäre dagegen eine Instanz mit einem Materialwert.')]),
    ('composition','Composition','Komposition','🧱',('An owning whole-part relationship in the stated model.','Eine besitzende Ganzes-Teil-Beziehung im angegebenen Modell.'),[
        ('door-composition','Door assembly owning its leaf','Türbaugruppe mit eigenem Türblatt','The door assembly owns a leaf component in this schematic model. A leaf is part of a door, not a subtype of Door.','Die Türbaugruppe besitzt in diesem schematischen Modell ein Türblatt als Bestandteil. Ein Blatt ist Teil einer Tür und kein Untertyp von Tür.'),
        ('wall-layer-composition','Wall assembly owning its layers','Wandaufbau mit eigenen Schichten','The wall is composed of owned layer components. A layer is part of the wall assembly rather than a specialized Wall class.','Die Wand besteht aus eigenen Schichtkomponenten. Eine Schicht ist Teil des Wandaufbaus und keine spezialisierte Wandklasse.'),
        ('stair-composition','Stair assembly owning its flights','Treppenbaugruppe mit eigenen Läufen','The stair owns its flight components as parts of the assembly. This is a whole-part relationship, not is-a specialization.','Die Treppe besitzt ihre Läufe als Teile der Baugruppe. Dies ist eine Ganzes-Teil-Beziehung und keine Ist-ein-Spezialisierung.'),
        ('window-frame-composition','Window assembly owning its frame','Fensterbaugruppe mit eigenem Rahmen','The frame belongs to the window assembly in this model. It is not another kind of Window.','Der Rahmen gehört in diesem Modell zur Fensterbaugruppe. Er ist keine andere Art von Fenster.'),
        ('roof-layer-composition','Roof assembly owning its layers','Dachaufbau mit eigenen Schichten','The roof owns insulation and covering components. Composition describes how these parts form the whole roof assembly.','Das Dach besitzt Dämmung und Deckung als Bestandteile. Komposition beschreibt, wie diese Teile den gesamten Dachaufbau bilden.')])])

coordination=task('model-coordination',('Interfaces and Coordination','Schnittstellen und Koordination'),'🤝',(
    'Distinguish a technical exchange interface from coordination and isolated work. An interface defines how systems exchange interpretable data; coordination establishes and checks shared decisions across disciplines. A file format alone cannot resolve clashes or responsibility. Classify the action emphasized in each example, not every activity it may support. Allow five minutes.',
    'Unterscheide technische Austausch-Schnittstellen, Koordination und isoliertes Arbeiten. Eine Schnittstelle legt fest, wie Systeme interpretierbare Daten austauschen; Koordination vereinbart und prüft gemeinsame Entscheidungen über Fachgrenzen hinweg. Ein Dateiformat allein löst weder Kollisionen noch Zuständigkeiten. Ordne die jeweils hervorgehobene Handlung ein. Plane fünf Minuten ein.'),[
    ('interface','Exchange interface','Austausch-Schnittstelle','🔌',('A defined technical contract for transferring and interpreting model or issue data.','Ein festgelegter technischer Vertrag zur Übertragung und Deutung von Modell- oder Vorgangsdaten.'),[
        ('ifc-delivery','IFC field mapping between tools','IFC-Feldzuordnung zwischen Werkzeugen','A mapping defines how object properties are encoded and interpreted across tools. This enables exchange; agreement on the building design still needs coordination.','Eine Zuordnung legt Kodierung und Deutung von Objekteigenschaften zwischen Werkzeugen fest. Sie ermöglicht Austausch; der Gebäudeentwurf muss weiterhin koordiniert werden.'),
        ('bcf-schema','BCF issue exchange contract','BCF-Vertrag zum Vorgangsaustausch','The structured issue exchange contract carries references and review context. Its technical format supports discussion but does not decide the solution.','Der strukturierte Austauschvertrag überträgt Vorgangsverweise und Prüfkontext. Sein technisches Format unterstützt die Diskussion, entscheidet aber keine Lösung.'),
        ('api-units','API contract for metres and IDs','API-Vertrag für Meter und Kennungen','Explicit units and stable identifiers make the receiving system interpret values consistently. The API contract describes the interface.','Ausdrückliche Einheiten und stabile Kennungen ermöglichen eine konsistente Deutung im empfangenden System. Der API-Vertrag beschreibt die Schnittstelle.'),
        ('property-schema','Shared property exchange schema','Gemeinsames Eigenschaftsaustauschschema','A schema fixes field names, value types and allowed structures for exchange. It cannot by itself guarantee that the values satisfy project needs.','Ein Schema legt Feldnamen, Werttypen und erlaubte Austauschstrukturen fest. Es garantiert allein nicht, dass die Werte die Projektanforderungen erfüllen.'),
        ('coordinate-contract','Coordinate system exchange contract','Austauschvertrag zum Koordinatensystem','The stated origin, orientation and length unit define how transmitted geometry is read. Choosing and checking that agreement across teams is a separate coordination activity.','Angegebener Ursprung, Orientierung und Längeneinheit bestimmen die Interpretation übertragener Geometrie. Auswahl und Prüfung dieser Vereinbarung über Teams hinweg sind Koordination.')]),
    ('coordination','Coordination','Koordination','🤝',('Agreement, review and resolution of shared interdisciplinary model decisions.','Abstimmung, Prüfung und Lösung gemeinsamer fachübergreifender Modellentscheidungen.'),[
        ('opening-agreement','Agreed duct opening in a beam','Abgestimmter Kanaldurchbruch im Träger','Structure and services jointly agree location and size after checking constraints. The shared design decision is coordination, whatever exchange format carries it.','Tragwerk und Gebäudetechnik vereinbaren Lage und Größe nach Prüfung der Randbedingungen. Diese gemeinsame Entwurfsentscheidung ist unabhängig vom Austauschformat Koordination.'),
        ('clash-report','Clash review with an assigned owner','Kollisionsprüfung mit Zuständigkeit','The team interprets the conflict, assigns responsibility and tracks its resolution. Detecting or exporting a clash alone would not complete this coordination.','Das Team bewertet den Konflikt, weist Verantwortung zu und verfolgt die Lösung. Das bloße Erkennen oder Exportieren einer Kollision schließt diese Koordination nicht ab.'),
        ('origin-agreement','Team agreement on a shared origin','Teamabstimmung zum gemeinsamen Ursprung','The disciplines choose a common reference and verify aligned models. This decision and check are coordination; the encoded coordinate contract is the interface.','Die Fachbereiche wählen einen gemeinsamen Bezug und prüfen die Modellausrichtung. Entscheidung und Kontrolle sind Koordination; der kodierte Koordinatenvertrag ist die Schnittstelle.'),
        ('requirement-review','Joint review of required properties','Gemeinsame Prüfung benötigter Angaben','The team agrees which information is required, by whom and when, then checks delivery. Those responsibilities exceed the syntax of an exchange file.','Das Team vereinbart benötigte Informationen, Zuständigkeiten und Termine und prüft die Lieferung. Diese Verantwortung geht über die Syntax einer Austauschdatei hinaus.'),
        ('change-review','Approved route change across trades','Fachübergreifend geprüfte Trassenänderung','The route change is reviewed for architectural, structural and service effects. The shared approval resolves a design dependency across disciplines.','Die Trassenänderung wird auf architektonische, statische und technische Folgen geprüft. Die gemeinsame Freigabe löst eine fachübergreifende Entwurfsabhängigkeit.')]),
    ('isolated-work','Isolated work','Isoliertes Arbeiten','🏝️',('Local work without a defined shared exchange or coordination step in the scenario.','Lokale Arbeit ohne festgelegten gemeinsamen Austausch oder Abstimmungsschritt im Beispiel.'),[
        ('native-silo','Private native file without exchange','Private native Datei ohne Austausch','The file stays with one author and no exchange contract or review is specified. Using an object-based tool alone does not establish interdisciplinary coordination.','Die Datei bleibt bei einer Person; Austauschvertrag und Prüfung fehlen. Ein objektbasiertes Werkzeug allein schafft noch keine fachübergreifende Koordination.'),
        ('silent-duct-edit','Unannounced private duct relocation','Unangekündigte private Kanalverlegung','Moving a duct without sharing the change or reviewing other models leaves dependencies unresolved. A local correction is not yet a coordinated change.','Eine Kanalverlegung ohne Mitteilung und Prüfung anderer Modelle lässt Abhängigkeiten offen. Eine lokale Korrektur ist noch keine koordinierte Änderung.'),
        ('unchecked-overlay','Private model overlay without review','Private Modellüberlagerung ohne Prüfung','Placing models together privately does not establish shared decisions, responsibilities or issue resolution. In this scenario no coordination step follows.','Eine private Modellüberlagerung schafft keine gemeinsamen Entscheidungen, Verantwortlichkeiten oder Lösungen. Im Beispiel folgt kein Abstimmungsschritt.'),
        ('local-property-edit','Unshared local property change','Ungeteilte lokale Eigenschaftsänderung','A property changed only in a private model has not passed through an agreed exchange or team review. The action remains isolated.','Eine nur im privaten Modell geänderte Eigenschaft hat weder vereinbarten Austausch noch Teamprüfung durchlaufen. Die Handlung bleibt isoliert.'),
        ('private-clash-image','Unshared private clash screenshot','Ungeteilter privater Kollisionsausschnitt','The screenshot records a local observation, but nobody receives or owns an issue. Without the stated sharing and review, the scenario is isolated work.','Das Bild hält eine lokale Beobachtung fest, aber niemand erhält oder verantwortet einen Vorgang. Ohne Weitergabe und Prüfung bleibt das Beispiel isoliertes Arbeiten.')])])

for task_value in [data,oop,coordination]:
    for item in task_value['items']:
        short={'door-width-meaning':('Door clear width','Lichte Türbreite'),'change-review':('Approved route change','Geprüfte Trassenänderung'),'private-clash-image':('Private clash screenshot','Privater Kollisionsausschnitt')}.get(item['id'])
        if short:
            item['short']=text(*short)

quiz={'$schema':'../../../../🧰️framework/🛍️products/📚️course/🧬️schema/🔣️.json#/$defs/Quiz','schema':'semio.quiz/v1','id':'bim-concepts','emoji':'🏗️','title':text('BIM Concepts','BIM-Grundlagen'),'description':text('Interpret building data, distinguish object-oriented concepts and coordinate models through explicit interfaces.','Gebäudedaten deuten, objektorientierte Konzepte unterscheiden und Modelle über ausdrückliche Schnittstellen koordinieren.'),'tasks':[data,oop,coordination]}
